sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    g_form.clearMessages();

    var gaBaseTable = new GlideAjax('BaseTableUtils');
    gaBaseTable.addParam('sysparm_name', 'checkVacancies');
    gaBaseTable.addParam('sysparm_baseid', newValue);
    gaBaseTable.getXMLAnswer(vacanciesCheck);

    //Type appropriate comment here, and begin script below

}

function vacanciesCheck(answer) {
    if (answer) {
        if (answer == true || answer == 'true') {
            g_form.clearValue("base");
            g_form.showFieldMsg("base", "There is no spots left for this base.", "error");
        }
        if (answer == false || answer == 'false') {
            // g_form.clearMessages();
            g_form.hideFieldMsg("base");
        }
    }
}
